// 雙向映射：記錄每個字元「上一次出現的位置」，兩邊必須一致
// 時間複雜度: O(n)，空間複雜度: O(1)（字元集固定）
function isIsomorphic(s, t) {
    const lastS = new Map();
    const lastT = new Map();
    for (let i = 0; i < s.length; i++) {
        if ((lastS.get(s[i]) ?? -1) !== (lastT.get(t[i]) ?? -1))
            return false;
        lastS.set(s[i], i);
        lastT.set(t[i], i);
    }
    return true;
}

